// ═══ THREADLOCAL — problems with virtual threads ═══
private static final ThreadLocal<String> currentUser = new ThreadLocal<>();

void processWithThreadLocal() {
    currentUser.set("Rajesh");      // mutable — can change anytime
    try {
        service.doWork();            // reads currentUser.get()
    } finally {
        currentUser.remove();        // ⚠ MUST manually remove! Forget → LEAK!
    }
    // With 1M virtual threads: 1M ThreadLocal copies → memory pressure!
}

// ═══ SCOPEDVALUE — designed for virtual threads ═══
private static final ScopedValue<String> CURRENT_USER = ScopedValue.newInstance();

void processWithScopedValue() {
    ScopedValue.where(CURRENT_USER, "Rajesh")  // immutable binding
        .run(() -> {
            service.doWork();  // reads CURRENT_USER.get() → "Rajesh"
            // Cannot change CURRENT_USER within this scope!
            // Automatically cleaned when run() exits — no manual remove()!
        });
    // CURRENT_USER.get() here → NoSuchElementException (scope exited)
}

// ═══ WITH STRUCTURED CONCURRENCY ═══
ScopedValue.where(CURRENT_USER, "Rajesh").run(() -> {
    try (var scope = new StructuredTaskScope.ShutdownOnFailure()) {
        // Child tasks INHERIT CURRENT_USER automatically — cheap!
        scope.fork(() -> auditLog(CURRENT_USER.get()));   // "Rajesh"
        scope.fork(() -> checkBalance(CURRENT_USER.get())); // "Rajesh"
        scope.join();
    }
});
