package com.bank.scoped;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class ScopedValueTest {

    static final ScopedValue<String> USER = ScopedValue.newInstance();

    @Test void scopedValueAvailableInScope() {
        ScopedValue.where(USER, "Rajesh").run(() -> {
            assertThat(USER.get()).isEqualTo("Rajesh");
        });
    }

    @Test void scopedValueNotAvailableOutsideScope() {
        assertThat(USER.isBound()).isFalse();
    }

    @Test void scopedValueInheritedByChildThread() throws Exception {
        ScopedValue.where(USER, "Priya").run(() -> {
            Thread vt = Thread.startVirtualThread(() -> {
                assertThat(USER.get()).isEqualTo("Priya");  // inherited!
            });
            try { vt.join(); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        });
    }

    @Test void nestedScopeOverrides() {
        ScopedValue.where(USER, "Rajesh").run(() -> {
            assertThat(USER.get()).isEqualTo("Rajesh");
            ScopedValue.where(USER, "Priya").run(() -> {
                assertThat(USER.get()).isEqualTo("Priya");  // inner scope
            });
            assertThat(USER.get()).isEqualTo("Rajesh");  // outer restored
        });
    }
}
