package com.bank.java8;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.assertThat;

class ScopedValueTest {

    static final ScopedValue<String> PRINCIPAL = ScopedValue.newInstance();

    String deepMethod() {
        return "processed for " + PRINCIPAL.get();   // reads bound value, no param passing
    }

    @Test
    void scopedValueBoundForDynamicExtent() {
        String result = ScopedValue.where(PRINCIPAL, "Rajesh")
            .call(this::deepMethod);                 // bound only inside this call

        assertThat(result).isEqualTo("processed for Rajesh");
        assertThat(PRINCIPAL.isBound()).isFalse();   // auto-unbound after the call
    }
}
